find_python() {
  local p
  for p in python3 python2 python; do
    if command -v "$p" >/dev/null 2>&1 &&
       "$p" -c 'import sys; assert sys.version_info >= (2,7)' 2>/dev/null; then
      PY=$p; return 0
    fi
  done
  die 'Python 2.7 or Python 3 is required. CentOS 7 normally includes Python 2.7.'
}
helper() {
 "$PY" - "$@" <<'PY_HELPER'
from __future__ import print_function
import base64, binascii, hashlib, hmac, json, os, re, socket, struct, sys, uuid, zipfile
try:
    from urllib.parse import urlencode, quote
except ImportError:
    from urllib import urlencode, quote

def ipv4(value):
    if not re.match(r'^\d{1,3}(\.\d{1,3}){3}$', value):
        raise ValueError('Not an IPv4 address')
    nums = list(map(int, value.split('.')))
    if any(x > 255 for x in nums):
        raise ValueError('Invalid IPv4 address')
    return sum(n << (24-8*i) for i,n in enumerate(nums))

def public4(value):
    n = ipv4(value)
    blocked = [('0.0.0.0',8),('10.0.0.0',8),('100.64.0.0',10),
        ('127.0.0.0',8),('169.254.0.0',16),('172.16.0.0',12),
        ('192.0.0.0',24),('192.0.2.0',24),('192.168.0.0',16),
        ('198.18.0.0',15),('198.51.100.0',24),('203.0.113.0',24),
        ('224.0.0.0',4),('240.0.0.0',4)]
    if any(n >> (32-bits) == ipv4(net) >> (32-bits) for net,bits in blocked):
        raise ValueError('A public unicast IPv4 address is required')
    return value

def hostname(value):
    if len(value)>253 or not all(re.match(r'^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$', x)
                                 for x in value.split('.')):
        raise ValueError('Invalid hostname')
    return value.lower()

def port(value):
    value=int(value)
    if not 1 <= value <= 65535:
        raise ValueError('Invalid TCP port')
    return value

def key(value):
    if not re.match(r'^[A-Za-z0-9_-]{43}$',value):
        raise ValueError('Invalid X25519 key')
    if len(base64.urlsafe_b64decode(value.encode('ascii')+b'='))!=32:
        raise ValueError('Invalid X25519 key length')
    return value

def read_state(path):
    with open(path) as f:
        s=json.load(f)
    if s.get('owner')!='bwh45-reality-v2' or s.get('schema')!=1:
        raise ValueError('Unknown state ownership/schema')
    key(s['private']); key(s['public'])
    if str(uuid.UUID(s['uuid']))!=s['uuid']:
        raise ValueError('Invalid UUID')
    if not re.match(r'^[0-9a-f]{16}$',s['short_id']):
        raise ValueError('Invalid ShortId')
    hostname(s['sni']); port(s['port'])
    if s['fp'] not in ('chrome','ios'):
        raise ValueError('Unsupported fingerprint')
    hostname(s['address'])
    if (s.get('ss') or {}).get('enabled'):
        ss_validate(s['ss'])
        if s['ss']['port']==s['port']: raise ValueError('VLESS and SS port conflict')
    return s

def emit(obj):
    print(json.dumps(obj,sort_keys=True,indent=2))

def server_v2(s,listen,number):
    return {'log':{'loglevel':'warning'},'inbounds':[{
        'listen':listen,'port':port(number),'protocol':'vless',
        'settings':{'clients':[{'id':s['uuid'],'flow':'xtls-rprx-vision'}],
                    'decryption':'none'},
        'streamSettings':{'network':'tcp','security':'reality',
            'realitySettings':{'show':False,'target':s['sni']+':443','xver':0,
                'serverNames':[s['sni']],'privateKey':s['private'],
                'shortIds':[s['short_id']]}}}],
        'outbounds':[{'protocol':'freedom','tag':'direct'}]}

def client(s,address,remote_port,socks_port):
    return {'log':{'loglevel':'warning'},'inbounds':[{
        'listen':'127.0.0.1','port':port(socks_port),'protocol':'socks',
        'settings':{'auth':'noauth','udp':False}}],
        'outbounds':[{'protocol':'vless','settings':{'vnext':[{
            'address':address,'port':port(remote_port),'users':[{
                'id':s['uuid'],'encryption':'none','flow':'xtls-rprx-vision'}]}]},
            'streamSettings':{'network':'tcp','security':'reality',
                'realitySettings':{'serverName':s['sni'],'fingerprint':s['fp'],
                    'publicKey':s['public'],'shortId':s['short_id'],'spiderX':'/'}}}]}

def link_v2(s):
    query=[('encryption','none'),('flow','xtls-rprx-vision'),('security','reality'),
        ('sni',s['sni']),('fp',s['fp']),('pbk',s['public']),('sid',s['short_id']),
        ('type','tcp'),('headerType','none'),('spx','/')]
    return 'vless://%s@%s:%s?%s#bwh45-REALITY' % (
        s['uuid'],s['address'],s['port'],urlencode(query))


def server(s,listen,number,include_ss=True):
    cfg=server_v2(s,listen,number)
    if include_ss and (s.get('ss') or {}).get('enabled'):
        cfg['inbounds'].append(ss_server(s,listen,s['ss']['port']))
    return cfg

def link(s):
    return link_v2(s).rsplit('#',1)[0]+'#'+quote(s.get('name','bwh45-REALITY').encode('utf-8'),safe='')

# Manager extension. QR code source is vendored BSD-3-Clause PyQRCode, not fetched at runtime.
def ss_data(s):
    t=s.get('ss') or {}
    if not t.get('enabled'): raise ValueError('Shadowsocks is not enabled; run v2ray ss first')
    return t

def ss_validate(t):
    port(t['port'])
    if t['method'] not in ('2022-blake3-aes-128-gcm','2022-blake3-aes-256-gcm','aes-256-gcm','chacha20-ietf-poly1305'):
        raise ValueError('Unsupported Shadowsocks method')
    if t['method'].startswith('2022-'):
        raw=base64.b64decode(t['password'].encode('ascii'))
        if len(raw)!=(16 if 'aes-128' in t['method'] else 32):
            raise ValueError('SS2022 requires a correctly sized Base64 key')
    elif len(t['password'])<16:
        raise ValueError('Shadowsocks password must be at least 16 characters')
    if any(ord(x)<32 for x in t['password']):
        raise ValueError('Control character in password')

def ss_server(s,listen,number):
    t=ss_data(s)
    return {'listen':listen,'port':port(number),'tag':'ss','protocol':'shadowsocks',
            'settings':{'method':t['method'],'password':t['password'],'network':'tcp,udp'}}

def ss_client(s,address,number,socks):
    t=ss_data(s)
    return {'log':{'loglevel':'warning'},'inbounds':[{'listen':'127.0.0.1',
        'port':port(socks),'protocol':'socks','settings':{'auth':'noauth','udp':True}}],
        'outbounds':[{'protocol':'shadowsocks','settings':{'servers':[{
            'address':address,'port':port(number),'method':t['method'],'password':t['password']} ]}}]}

def ss_uri(s):
    t=ss_data(s)
    user=t['method']+':'+t['password']
    if t['method'].startswith('2022-'):
        user=quote(t['method'].encode('utf-8'),safe='')+':'+quote(t['password'].encode('utf-8'),safe='')
    else:
        user=base64.urlsafe_b64encode(user.encode('utf-8')).decode('ascii').rstrip('=')
    return 'ss://'+user+'@'+s['address']+':'+str(t['port'])+'#'+quote((s.get('name','bwh45-REALITY')+'-SS').encode('utf-8'),safe='')

def qr_package():
    import types
    bundle=json.loads(base64.b64decode('').decode('utf-8'))
    pkg=types.ModuleType('pyqrcode');pkg.__path__=[];sys.modules['pyqrcode']=pkg
    for name,path in [('pyqrcode.tables','pyqrcode/tables.py'),('pyqrcode.builder','pyqrcode/builder.py'),('pyqrcode','pyqrcode/__init__.py')]:
        mod=sys.modules.get(name) or types.ModuleType(name)
        mod.__file__='<vendored '+path+'>';mod.__package__='pyqrcode';sys.modules[name]=mod
        exec(compile(bundle[path].encode('utf-8'),mod.__file__,'exec'),mod.__dict__)
        if '.' in name: setattr(pkg,name.rsplit('.',1)[1],mod)
    return pkg,bundle['License']

def qr_file(value,path):
    pkg,_=qr_package()
    pkg.create(value,error='M',mode='binary',encoding='utf-8').svg(path,scale=6,background='#fff')

def exports(s,folder):
    if not os.path.isdir(folder): os.makedirs(folder,0o700)
    values={'client.json':json.dumps(client(s,s['address'],s['port'],10808),indent=2),
            'info.txt':info_text(s),'uri.txt':link(s)}
    if (s.get('ss') or {}).get('enabled'):
        values.update({'ss-client.json':json.dumps(ss_client(s,s['address'],s['ss']['port'],10808),indent=2),
                       'ss-info.txt':ss_text(s),'ss-uri.txt':ss_uri(s)})
    for name,value in values.items():
        data=value.encode('utf-8')
        with open(os.path.join(folder,name),'wb') as f: f.write(data)
        os.chmod(os.path.join(folder,name),0o600)
    if not (s.get('ss') or {}).get('enabled'):
        for name in ('ss-client.json','ss-info.txt','ss-uri.txt','ss-qr.svg'):
            stale=os.path.join(folder,name)
            if os.path.isfile(stale) or os.path.islink(stale): os.unlink(stale)
    qr_file(link(s),os.path.join(folder,'qr.svg'))
    if (s.get('ss') or {}).get('enabled'): qr_file(ss_uri(s),os.path.join(folder,'ss-qr.svg'))

def info_text(s):
    rows=[('Server',s['address']),('Port',s['port']),('Protocol','VLESS'),('Transport','TCP'),
        ('Security','REALITY'),('Flow','xtls-rprx-vision'),('SNI',s['sni']),('Fingerprint',s['fp']),
        ('UUID',s['uuid']),('PublicKey (Password)',s['public']),('ShortId',s['short_id'])]
    return '\n'.join('%s: %s'%x for x in rows)+'\n\n'+link(s)+'\n'

def ss_text(s):
    t=ss_data(s)
    return 'Server: %s\nPort: %s\nMethod: %s\nPassword: %s\nNetwork: TCP + UDP\n\n%s\n' % (
        s['address'],t['port'],t['method'],t['password'],ss_uri(s))

def share_meta(path):
    with open(path) as f: m=json.load(f)
    if m.get('owner')!='bwh45-reality-v2' or not re.match(r'^[a-f0-9]{48}$',m['token']):
        raise ValueError('Invalid sharing metadata')
    port(m['port']);hostname(m['host'])
    if not os.path.isabs(m['folder']) or os.path.islink(m['folder']): raise ValueError('Unsafe sharing folder')
    return m

def share_token(m,name):
    if name not in ('client.json','info.txt','uri.txt','qr.svg','ss-client.json','ss-info.txt','ss-uri.txt','ss-qr.svg'):
        raise ValueError('Unknown sharing file')
    return hmac.new(m['token'].encode('ascii'),name.encode('ascii'),hashlib.sha256).hexdigest()[:48]

def serve_share(path):
    import ssl,time,threading
    try:
        from http.server import BaseHTTPRequestHandler,HTTPServer
        from socketserver import ThreadingMixIn
    except ImportError:
        from BaseHTTPServer import BaseHTTPRequestHandler,HTTPServer
        from SocketServer import ThreadingMixIn
    m=share_meta(path)
    allowed=set(['client.json','info.txt','uri.txt','qr.svg','ss-client.json','ss-info.txt','ss-uri.txt','ss-qr.svg'])
    class Handler(BaseHTTPRequestHandler):
        def log_message(self,*args): pass
        def do_GET(self):
            if time.time()>=m['expires']: self.send_error(410);return
            parts=self.path.split('/')
            name=parts[-1] if len(parts)==3 else ''
            if name not in allowed: self.send_error(404);return
            expected='/'+share_token(m,name)+'/'+name
            equal=getattr(hmac,'compare_digest',lambda x,y:len(x)==len(y) and sum(ord(a)^ord(b) for a,b in zip(x,y))==0)
            file=os.path.join(m['folder'],name)
            if not equal(self.path,expected) or not os.path.isfile(file) or os.path.islink(file):
                self.send_error(404);return
            with open(file,'rb') as f: data=f.read()
            self.send_response(200)
            self.send_header('Content-Type','image/svg+xml' if name.endswith('.svg') else 'application/json' if name.endswith('.json') else 'text/plain; charset=utf-8')
            self.send_header('Cache-Control','no-store')
            self.send_header('X-Content-Type-Options','nosniff')
            self.send_header('Content-Length',str(len(data)))
            self.end_headers()
            try: self.wfile.write(data)
            except (socket.error,IOError): pass
    proto=getattr(ssl,'PROTOCOL_TLS_SERVER',getattr(ssl,'PROTOCOL_TLS',ssl.PROTOCOL_SSLv23))
    context=ssl.SSLContext(proto)
    context.options|=getattr(ssl,'OP_NO_TLSv1',0)|getattr(ssl,'OP_NO_TLSv1_1',0)
    if hasattr(context,'set_ecdh_curve'): context.set_ecdh_curve('prime256v1')
    context.load_cert_chain(m['cert'],m['key'])
    class Server(ThreadingMixIn,HTTPServer):
        daemon_threads=True
        allow_reuse_address=True
        def handle_error(self,*args): pass
        def get_request(self):
            sock,addr=self.socket.accept();sock.settimeout(5)
            return context.wrap_socket(sock,server_side=True,do_handshake_on_connect=False),addr
    server=Server(('0.0.0.0',m['port']),Handler);server.timeout=0.5
    while time.time()<m['expires']: server.handle_request()
    server.server_close()

def udp_test(socks_port):
    import threading
    echo=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);echo.bind(('127.0.0.1',0));echo.settimeout(7)
    payload=b'bwh45-udp-check-'+binascii.hexlify(os.urandom(8))
    def worker():
        try:
            data,addr=echo.recvfrom(4096);echo.sendto(data,addr)
        except socket.error: pass
        finally: echo.close()
    thread=threading.Thread(target=worker);thread.daemon=True;thread.start()
    control=socket.create_connection(('127.0.0.1',port(socks_port)),7);control.settimeout(7)
    control.sendall(b'\x05\x01\x00')
    if control.recv(2)!=b'\x05\x00': raise ValueError('SOCKS authentication failed')
    control.sendall(b'\x05\x03\x00\x01'+socket.inet_aton('127.0.0.1')+b'\x00\x00')
    reply=control.recv(64)
    if reply[:4]!=b'\x05\x00\x00\x01': raise ValueError('SOCKS UDP association failed')
    relay=(socket.inet_ntoa(reply[4:8]),struct.unpack('!H',reply[8:10])[0])
    data=b'\x00\x00\x00\x01'+socket.inet_aton('127.0.0.1')+struct.pack('!H',echo.getsockname()[1])+payload
    udp=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);udp.settimeout(7);udp.sendto(data,relay)
    response,_=udp.recvfrom(4096)
    if not response.endswith(payload): raise ValueError('UDP reply mismatch')
    udp.close();control.close();thread.join(0.2)
    print('PASS: native Shadowsocks UDP relay')

def manager_ops(op,a):
    if op=='self-check':
        pkg,license=qr_package()
        assert 'Michael Nooner' in license and pkg.create('test').code
        print('Manager helper and bundled QR generator OK');return
    if op=='qr-license': print(qr_package()[1]);return
    if op=='serve-share': serve_share(a[0]);return
    if op=='udp-test': udp_test(a[0]);return
    if op=='share-token': print(share_token(share_meta(a[0]),a[1]));return
    if op=='meta-field':
        m=share_meta(a[0])
        if a[1] not in ('token','host','port','expires','folder','cert','key'): raise ValueError('Unknown sharing field')
        print(m[a[1]]);return
    if op=='make-share':
        import time
        ttl=int(a[3])
        if not 1<=ttl<=3600: raise ValueError('Share TTL must be 1..3600 seconds')
        emit({'owner':'bwh45-reality-v2','token':binascii.hexlify(os.urandom(24)).decode('ascii'),
            'host':hostname(a[0]),'port':port(a[1]),'folder':os.path.abspath(a[2]),
            'cert':os.path.abspath(a[4]),'key':os.path.abspath(a[5]),'expires':int(time.time())+ttl})
        return
    if op=='repo-head':
        with open(a[0]) as f: result=json.load(f)
        value=result['object']['sha']
        if not re.match(r'^[0-9a-f]{40}$',value): raise ValueError('Invalid repository commit')
        print(value);return
    if op=='manifest':
        with open(a[0]) as f: m=json.load(f)
        if not re.match(r'^\d+\.\d+\.\d+$',m['version']) or not re.match(r'^[a-f0-9]{64}$',m['sha256']):
            raise ValueError('Invalid update manifest')
        print(m['version']+' '+m['sha256']);return
    s=read_state(a[0])
    if op=='patch':
        field=a[1]
        if field=='rekey':
            with open(a[2]) as f: lines=f.read().splitlines()
            fields={}
            for line in lines:
                if ':' not in line: continue
                label,v=line.split(':',1);label=re.sub(r'[\s_-]+','',label).lower();fields[label]=v.strip()
            s['private']=key(fields.get('privatekey',''))
            s['public']=key(fields.get('password(publickey)',fields.get('password',fields.get('publickey',''))))
            s['short_id']=binascii.hexlify(os.urandom(8)).decode('ascii')
        else:
            with open(a[2]) as f: value=f.read().strip()
            if field=='port': s[field]=port(value)
            elif field in ('address','sni'): s[field]=hostname(value)
            elif field=='fp':
                if value not in ('chrome','ios'): raise ValueError('Unsupported fingerprint')
                s[field]=value
            elif field=='uuid': s[field]=str(uuid.UUID(value))
            elif field=='name':
                if not 1<=len(value)<=80 or any(ord(c)<32 for c in value): raise ValueError('Invalid node name')
                s[field]=value
            else: raise ValueError('Unknown editable field')
        if (s.get('ss') or {}).get('enabled') and s['port']==s['ss']['port']: raise ValueError('VLESS and SS ports conflict')
        emit(s)
    elif op=='ss-patch':
        old=s.get('ss') or {}
        if a[1]=='off': old['enabled']=False;s['ss']=old;emit(s);return
        method=a[3] or old.get('method','2022-blake3-aes-128-gcm')
        password=''
        if a[4]:
            with open(a[4]) as f: password=f.read().strip()
        if not password and old.get('method')==method: password=old.get('password','')
        if not password: password=base64.b64encode(os.urandom(16 if method=='2022-blake3-aes-128-gcm' else 32)).decode('ascii')
        t={'enabled':True,'port':port(a[2] or old.get('port',8388)),'method':method,'password':password}
        ss_validate(t)
        if t['port']==s['port']: raise ValueError('VLESS and SS ports conflict')
        s['ss']=t;emit(s)
    elif op=='ss-field':
        t=s.get('ss') or {}
        if a[1]=='enabled': print('1' if t.get('enabled') else '0')
        elif a[1] in ('port','method'): print(t[a[1]])
        else: raise ValueError('Not a printable SS field')
    elif op=='ss-server':
        emit({'log':{'loglevel':'warning'},'inbounds':[ss_server(s,a[1],a[2])],'outbounds':[{'protocol':'freedom'}]})
    elif op=='ss-client': emit(ss_client(s,a[1],a[2],a[3]))
    elif op=='ss-uri': print(ss_uri(s))
    elif op=='ss-text': print(ss_text(s))
    elif op=='exports': exports(s,a[1])
    elif op=='core-version':
        if not re.match(r'^\d+\.\d+\.\d+$',a[1]): raise ValueError('Invalid core version')
        s['core_version']=a[1];emit(s)
    else: raise ValueError('Unknown manager operation')

def main():
    op=sys.argv[1]; a=sys.argv[2:]
    if op in ('self-check','qr-license','serve-share','udp-test','meta-field','share-token','make-share','repo-head','manifest','patch','ss-patch','ss-field','ss-server','ss-client','ss-uri','ss-text','exports','core-version'):
        manager_ops(op,a);return
    if op=='public-ip':
        with open(a[0]) as f: data=f.read()
        for candidate in re.findall(r'(?<![\d.])\d{1,3}(?:\.\d{1,3}){3}(?![\d.])',data):
            try:
                print(public4(candidate)); return
            except ValueError: pass
        raise ValueError('No public IPv4 found')
    if op=='address':
        value=hostname(a[0]); expected=public4(a[1])
        addresses=set(x[4][0] for x in socket.getaddrinfo(value,443,socket.AF_INET,socket.SOCK_STREAM))
        if expected not in addresses:
            raise ValueError('SERVER_ADDRESS does not resolve to this VPS public IPv4')
        print(value); return
    if op=='hostname':
        print(hostname(a[0])); return
    if op=='resolve':
        addresses=sorted(set(x[4][0] for x in socket.getaddrinfo(hostname(a[0]),443,socket.AF_INET,socket.SOCK_STREAM)))
        for ip in addresses:
            print(public4(ip))
        return
    if op=='free-port':
        sock=socket.socket(); sock.bind(('127.0.0.1',0))
        print(sock.getsockname()[1]); sock.close(); return
    if op=='listening':
        sock=socket.socket(); sock.settimeout(0.3)
        try: sock.connect(('127.0.0.1',port(a[0])))
        finally: sock.close()
        return
    if op=='extract':
        with zipfile.ZipFile(a[0]) as archive:
            data=archive.read('xray')
        with open(a[1],'wb') as f: f.write(data)
        return
    if op=='state':
        with open(a[0]) as f: output=f.read()
        fields={}
        for line in output.splitlines():
            if ':' not in line: continue
            label,value=line.split(':',1)
            label=re.sub(r'[\s_-]+','',label).lower()
            if label in ('privatekey','publickey','password','password(publickey)'):
                if label in fields: raise ValueError('Duplicate key label')
                fields[label]=value.strip()
        private=key(fields.get('privatekey',''))
        public=key(fields.get('password(publickey)',fields.get('password',fields.get('publickey',''))))
        with open(a[1]) as f: ident=str(uuid.UUID(f.read().strip()))
        fp=a[6]
        if fp not in ('chrome','ios'): raise ValueError('Unsupported fingerprint')
        emit({'schema':1,'owner':'bwh45-reality-v2','uuid':ident,'private':private,
              'public':public,'short_id':binascii.hexlify(os.urandom(8)).decode('ascii'),
              'address':hostname(a[2]),'port':port(a[3]),'sni':hostname(a[4]),
              'core_version':a[5],'fp':fp})
        return
    s=read_state(a[0])
    if op=='server': emit(server(s,a[1],a[2],len(a)<4 or a[3]!='vless-only'))
    elif op=='client': emit(client(s,a[1],a[2],a[3]))
    elif op=='uri': print(link(s))
    elif op=='field':
        if a[1] not in ('address','port','sni','fp','core_version'):
            raise ValueError('Not a printable field')
        print(s[a[1]])
    elif op=='text':
        for label,value in [('Server',s['address']),('Port',s['port']),('Protocol','VLESS'),
            ('Transport','TCP'),('Security','REALITY'),('Flow','xtls-rprx-vision'),
            ('SNI',s['sni']),('Fingerprint',s['fp']),('UUID',s['uuid']),
            ('PublicKey (Password)',s['public']),('ShortId',s['short_id'])]:
            print('%s: %s' % (label,value))
        print('\nImport this complete line into v2rayN:\n'+link(s))
    else: raise ValueError('Unknown helper operation')
try:
    main()
except Exception as exc:
    # Do not echo input data or tracebacks containing configuration/keys.
    sys.stderr.write('Validation failed: '+str(exc)+'\n')
    sys.exit(1)
PY_HELPER
}
stop_pair() {
  local pid
  for pid in "$CLIENT_PID" "$SERVER_PID"; do
    if [[ -n "$pid" ]]; then kill "$pid" 2>/dev/null || true; wait "$pid" 2>/dev/null || true; fi
  done
  CLIENT_PID= SERVER_PID=
}
save_iptables() {
  if systemctl is-active --quiet iptables.service && [[ -x /etc/init.d/iptables ]]; then
    /etc/init.d/iptables save >/dev/null
  fi
}
undo_firewall() {
  case "$FW_KIND" in
    firewalld)
      [[ "$FW_RUNTIME" == 0 ]] || firewall-cmd --zone="$FW_ZONE" --remove-port="$PORT/tcp" >/dev/null 2>&1 || true
      [[ "$FW_PERMANENT" == 0 ]] || firewall-cmd --permanent --zone="$FW_ZONE" --remove-port="$PORT/tcp" >/dev/null 2>&1 || true ;;
    iptables)
      if [[ "$FW_ADDED" == 1 ]]; then
        iptables -D INPUT -p tcp --dport "$PORT" -m comment --comment "$OWNER" -j ACCEPT 2>/dev/null || true
        save_iptables || true
      fi ;;
    ufw)
      [[ "$FW_ADDED" == 0 ]] || ufw --force delete allow "$PORT/tcp" >/dev/null 2>&1 || true ;;
  esac
}
cleanup() {
  local rc=$?
  trap - EXIT INT TERM
  stop_pair
  if [[ -n "$TX_BACKUP" && -d "$TX_BACKUP/state" ]];then
    say "Restoring the previous node state from $TX_BACKUP" >&2
    cp -a -- "$TX_BACKUP/state/." "$BASE/" || true
    if [[ "$TX_CORE" == 1 && -f "$TX_BACKUP/xray" ]];then
      install -m 700 "$TX_BACKUP/xray" "$LIB/.xray-rollback" &&
        mv -f -- "$LIB/.xray-rollback" "$BIN" || true
    fi
    if [[ "$TX_RUNNING" == 1 ]];then systemctl restart "$SERVICE" >&2 || true
    else systemctl stop "$SERVICE" >/dev/null 2>&1 || true;fi
    undo_firewall
    TX_BACKUP=
  fi
  if [[ "$OWNED" == 1 && "$COMMITTED" == 0 ]]; then
    say 'Rolling back this incomplete installation.' >&2
    systemctl stop "$SERVICE" >/dev/null 2>&1 || true
    systemctl disable "$SERVICE" >/dev/null 2>&1 || true
    rm -f -- "$UNIT" "$INFO"
    if [[ "$CLI_CREATED" == 1 && -f "$LAUNCHER" ]];then rm -f -- "$LAUNCHER";fi
    if [[ -f "$BASE/.owner" && $(cat "$BASE/.owner") == "$OWNER" ]]; then rm -rf -- "$BASE" "$LIB"; fi
    systemctl daemon-reload >/dev/null 2>&1 || true
    undo_firewall
  fi
  if [[ -n "$WORK" && "$WORK" == /tmp/bwh45-reality.* && -d "$WORK" ]]; then rm -rf -- "$WORK"; fi
  if [[ "$rc" != 0 ]]; then
    printf '\nOperation failed. Review the diagnostic output above.\n' >&2
  fi
  exit "$rc"
}
port_busy() {
  ss -lnt | awk -v end=":$1$" 'NR>1 && $4 ~ end {found=1} END {exit !found}'
}
wait_listener() {
  local number=$1 pid=$2 n
  for n in {1..50}; do
    kill -0 "$pid" 2>/dev/null || return 1
    if helper listening "$number" >/dev/null 2>&1; then return 0; fi
    sleep 0.2
  done
  return 1
}
download_core() {
  local archive=$WORK/xray.zip actual
  fetch "https://github.com/XTLS/Xray-core/releases/download/v$CORE_VERSION/Xray-linux-64.zip" -o "$archive"
  actual=$(sha256sum "$archive" | awk '{print $1}')
  [[ "$actual" == "$CORE_SHA256" ]] || die 'Official Xray archive SHA256 mismatch.'
  helper extract "$archive" "$WORK/xray"
  chmod 700 "$WORK/xray"
  XRAY=$WORK/xray
  "$XRAY" version
}
public_address() {
  local url candidate
  for url in https://api.ipify.org https://ipv4.icanhazip.com https://checkip.amazonaws.com; do
    if fetch -4 --noproxy '*' --max-time 12 "$url" -o "$WORK/public-ip" &&
       candidate=$(helper public-ip "$WORK/public-ip" 2>/dev/null); then
      PUBLIC_IP=$candidate; break
    fi
  done
  if [[ -z "${PUBLIC_IP:-}" ]]; then
    ip -4 -o addr show scope global > "$WORK/interfaces"
    PUBLIC_IP=$(helper public-ip "$WORK/interfaces") || die 'Could not determine this VPS public IPv4.'
  fi
  ADDRESS=$PUBLIC_IP
  if [[ -n "${SERVER_ADDRESS:-}" ]]; then ADDRESS=$(helper address "$SERVER_ADDRESS" "$PUBLIC_IP"); fi
  say "Client address: $ADDRESS (detected public IPv4: $PUBLIC_IP)"
}
proxy_requests() {
  local socks_port=$1 url code round selected=''
  for url in https://www.gstatic.com/generate_204 https://www.microsoft.com/ https://example.com/; do
    if code=$(curl -q -fsS --proxy "socks5h://127.0.0.1:$socks_port" --noproxy '' \
      --connect-timeout 7 --max-time 18 -o /dev/null -w '%{http_code}' "$url" 2>"$WORK/https-error") &&
       [[ "$code" =~ ^[23][0-9][0-9]$ ]]; then selected=$url; break; fi
  done
  [[ -n "$selected" ]] || return 1
  for round in 1 2; do
    code=$(curl -q -fsS --proxy "socks5h://127.0.0.1:$socks_port" --noproxy '' \
      --connect-timeout 7 --max-time 18 -o /dev/null -w '%{http_code}' "$selected" 2>"$WORK/https-error") || return 1
    [[ "$code" =~ ^[23][0-9][0-9]$ ]] || return 1
  done
  say "PASS: 3 independent HTTPS requests through REALITY/Vision ($selected)."
}
test_proxy() {
  local state=$1 remote_port=$2 start_server=$3 socks_port
  stop_pair
  if [[ "$start_server" == 1 ]]; then
    helper server "$state" 127.0.0.1 "$remote_port" vless-only > "$WORK/test-server.json" || return 1
    "$XRAY" run -test -config "$WORK/test-server.json" >"$WORK/config-test.log" 2>&1 || return 1
    "$XRAY" run -config "$WORK/test-server.json" >"$WORK/server.log" 2>&1 9>&- &
    SERVER_PID=$!
    wait_listener "$remote_port" "$SERVER_PID" || { stop_pair; return 1; }
  fi
  socks_port=$(helper free-port) || { stop_pair; return 1; }
  helper client "$state" 127.0.0.1 "$remote_port" "$socks_port" > "$WORK/test-client.json" || { stop_pair; return 1; }
  "$XRAY" run -test -config "$WORK/test-client.json" >"$WORK/client-config-test.log" 2>&1 || { stop_pair; return 1; }
  "$XRAY" run -config "$WORK/test-client.json" >"$WORK/client.log" 2>&1 9>&- &
  CLIENT_PID=$!
  if ! wait_listener "$socks_port" "$CLIENT_PID" || ! proxy_requests "$socks_port"; then
    stop_pair; return 1
  fi
  stop_pair
}
choose_target() {
  local name ip test_port candidates
  candidates="${SNI:-www.amazon.com dl.google.com www.cloudflare.com}"
  for name in $candidates; do
    helper hostname "$name" >/dev/null || return 1
    say "Testing REALITY target: $name"
    if ! helper resolve "$name" > "$WORK/target-ips"; then continue; fi
    ip=$(head -n 1 "$WORK/target-ips")
    [[ -n "$ip" ]] || continue
    if ! timeout 22 "$XRAY" tls ping -ip "$ip" "$name" >"$WORK/tls-ping.log" 2>&1; then
      say "Target did not complete its TLS probe: $name"; continue
    fi
    if ! awk '/^Pinging with SNI/{part=1} part && /TLS Version:[[:space:]]+TLS 1.3/{ok=1} END{exit !ok}' "$WORK/tls-ping.log"; then
      say "Target did not pass verified TLS 1.3: $name"; continue
    fi
    helper state "$WORK/keys" "$WORK/uuid" "$ADDRESS" "$PORT" "$name" "$CORE_VERSION" "$FINGERPRINT" > "$WORK/state.json"
    test_port=$(helper free-port)
    if test_proxy "$WORK/state.json" "$test_port" 1; then
      say "Selected and proxy-tested target: $name"; return 0
    fi
    say "Target failed the real proxy test: $name"
  done
  die 'No target passed TLS 1.3 plus real REALITY/Vision HTTPS tests. Nothing was installed.'
}
allow_firewall() {
  local iface rc
  if command -v firewall-cmd >/dev/null 2>&1 && systemctl is-active --quiet firewalld.service; then
    FW_KIND=firewalld
    iface=$(ip -4 route show default | awk 'NR==1 {for(i=1;i<NF;i++)if($i=="dev"){print $(i+1);exit}}')
    FW_ZONE=$(firewall-cmd --get-zone-of-interface="$iface" 2>/dev/null || true)
    if [[ -z "$FW_ZONE" || "$FW_ZONE" == 'no zone' ]]; then FW_ZONE=$(firewall-cmd --get-default-zone); fi
    [[ "$FW_ZONE" =~ ^[A-Za-z0-9_-]+$ ]] || die 'Could not identify the active firewalld zone.'
    if firewall-cmd --zone="$FW_ZONE" --query-port="$PORT/tcp" >/dev/null; then :; else
      rc=$?; [[ "$rc" == 1 ]] || die 'firewalld runtime query failed.'
      FW_RUNTIME=1; firewall-cmd --zone="$FW_ZONE" --add-port="$PORT/tcp" >/dev/null
    fi
    if firewall-cmd --permanent --zone="$FW_ZONE" --query-port="$PORT/tcp" >/dev/null; then :; else
      rc=$?; [[ "$rc" == 1 ]] || die 'firewalld permanent query failed.'
      FW_PERMANENT=1; firewall-cmd --permanent --zone="$FW_ZONE" --add-port="$PORT/tcp" >/dev/null
    fi
  elif command -v ufw >/dev/null 2>&1 && ufw status | awk '/^Status: active$/{yes=1}END{exit !yes}'; then
    FW_KIND=ufw
    if ! ufw status | awk -v p="$PORT" '$1==p"/tcp" && /ALLOW/ {yes=1} END{exit !yes}'; then
      FW_ADDED=1; ufw allow "$PORT/tcp" comment "$OWNER" >/dev/null
    fi
  elif command -v iptables >/dev/null 2>&1; then
    FW_KIND=iptables
    if ! iptables -C INPUT -p tcp --dport "$PORT" -m comment --comment "$OWNER" -j ACCEPT 2>/dev/null; then
      FW_ADDED=1
      iptables -I INPUT 1 -p tcp --dport "$PORT" -m comment --comment "$OWNER" -j ACCEPT
    fi
    save_iptables
  else
    say 'No supported host firewall tool found. Provider firewall still requires TCP access.'
  fi
}
write_unit() {
  cat > "$UNIT" <<SERVICE_UNIT
# Managed by bwh45-reality-v2
[Unit]
Description=bwh45 VLESS REALITY Vision
After=network-online.target nss-lookup.target
Wants=network-online.target

[Service]
Type=simple
User=root
ExecStart=$BIN run -config $CONFIG
Restart=on-failure
RestartPreventExitStatus=23
RestartSec=3
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
SERVICE_UNIT
  chmod 644 "$UNIT"
}
guard_owned() {
  local p
  for p in "$BASE" "$LIB" "$UNIT" "$INFO"; do [[ ! -L "$p" ]] || die "Refusing symbolic link: $p"; done
  [[ -f "$BASE/.owner" && ! -L "$BASE/.owner" && $(cat "$BASE/.owner") == "$OWNER" ]] || die 'Unknown or missing installation owner.'
  [[ -f "$STATE" && ! -L "$STATE" && -f "$CONFIG" && ! -L "$CONFIG" && -x "$BIN" && ! -L "$BIN" ]] || die 'Installation is incomplete; inspect its files before retrying.'
  [[ -f "$UNIT" ]] && head -n 1 "$UNIT" | awk '$0=="# Managed by bwh45-reality-v2"{ok=1} END{exit !ok}' || die 'Unknown service unit.'
  helper field "$STATE" port >/dev/null
}
check_installed() {
  guard_owned
  XRAY=$BIN
  PORT=$(helper field "$STATE" port)
  "$XRAY" run -test -config "$CONFIG"
  systemctl is-active --quiet "$SERVICE" || die "Service is not running: $SERVICE"
  test_proxy "$STATE" "$PORT" 0 || {
    journalctl -u "$SERVICE" -n 25 --no-pager >&2 || true
    die 'The installed service failed its real REALITY/Vision proxy test.'
  }
  helper text "$STATE"
  say 'Server-side end-to-end checks passed. Import the link and verify from your client network.'
}
uninstall_owned() {
  guard_owned
  local backup
  backup=$(mktemp -d /root/bwh45-reality-backup.XXXXXX)
  cp -a -- "$BASE" "$backup/config"
  cp -a -- "$UNIT" "$backup/"
  [[ ! -f "$INFO" ]] || cp -a -- "$INFO" "$backup/"
  systemctl stop "$SERVICE"
  systemctl disable "$SERVICE"
  rm -f -- "$UNIT" "$INFO"
  rm -rf -- "$BASE" "$LIB"
  systemctl daemon-reload
  say "Uninstalled. Private configuration backup: $backup"
  say 'Host firewall rules were preserved.'
}
install_main() {
  local mode=${1:---install} tool path
  case "$mode" in --install|--check|--uninstall) ;; --help) say 'Usage: install.sh [--install|--check|--uninstall]'; return 0;; *) die 'Unknown option.';; esac
  [[ $(id -u) == 0 ]] || die 'Run as root on the bwh45 VPS.'
  [[ $(uname -s) == Linux && $(uname -m) == x86_64 ]] || die 'This installer targets Linux x86_64.'
  [[ -d /run/systemd/system ]] || die 'A running systemd host is required.'
  for tool in curl systemctl ss ip awk sha256sum timeout mktemp install cp chmod head flock; do
    command -v "$tool" >/dev/null 2>&1 || die "Missing command: $tool"
  done
  [[ ! -L /run/bwh45-reality.lock ]] || die 'Unsafe lock path.'
  exec 9>/run/bwh45-reality.lock
  flock -n 9 || die 'Another bwh45 installation/check is running.'
  find_python
  WORK=$(mktemp -d /tmp/bwh45-reality.XXXXXX)
  trap cleanup EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  if [[ "$mode" == --uninstall ]]; then uninstall_owned; return; fi
  if [[ -e "$BASE" ]]; then
    guard_owned
    if [[ "$mode" == --install ]]; then systemctl start "$SERVICE"; fi
    manager_install
    check_installed; return
  fi
  [[ "$mode" == --install ]] || die 'This installer has not installed a node yet.'
  [[ "$PORT" =~ ^[0-9]+$ && "$PORT" -ge 1 && "$PORT" -le 65535 ]] || die 'Invalid PORT.'
  [[ "$FINGERPRINT" == chrome || "$FINGERPRINT" == ios ]] || die 'FINGERPRINT must be chrome or ios.'
  for path in "$BASE" "$LIB" "$UNIT" "$UNIT.d" "$INFO"; do
    [[ ! -e "$path" && ! -L "$path" ]] || die "Existing file requires review: $path"
  done
  if port_busy "$PORT"; then
    ss -lntp >&2
    die "TCP $PORT is occupied. Stop/uninstall its previous owner first."
  fi
  say '[1/7] Downloading and verifying the pinned official Xray core...'
  download_core
  say '[2/7] Detecting this VPS address and generating independent credentials...'
  public_address
  "$XRAY" uuid > "$WORK/uuid"
  "$XRAY" x25519 > "$WORK/keys"
  say '[3/7] Selecting a TLS target and testing real REALITY/Vision HTTPS traffic...'
  choose_target
  say '[4/7] Validating the final server and client configurations...'
  helper server "$WORK/state.json" 0.0.0.0 "$PORT" > "$WORK/config.json"
  helper client "$WORK/state.json" "$ADDRESS" "$PORT" 10808 > "$WORK/export-client.json"
  "$XRAY" run -test -config "$WORK/config.json"
  "$XRAY" run -test -config "$WORK/export-client.json"
  say '[5/7] Installing a dedicated systemd service and allowing its TCP port...'
  install -d -m 700 "$BASE" "$LIB"
  printf '%s\n' "$OWNER" > "$BASE/.owner"
  OWNED=1
  install -m 700 "$XRAY" "$BIN"
  install -m 600 "$WORK/state.json" "$STATE"
  install -m 600 "$WORK/config.json" "$CONFIG"
  install -m 600 "$WORK/export-client.json" "$BASE/client.json"
  write_unit
  allow_firewall
  say '[6/7] Starting the actual service and testing it through a real client...'
  systemctl daemon-reload
  systemctl start "$SERVICE"
  XRAY=$BIN
  for attempt in {1..50}; do
    if systemctl is-active --quiet "$SERVICE" && helper listening "$PORT" >/dev/null 2>&1; then break; fi
    sleep 0.2
  done
  if ! test_proxy "$STATE" "$PORT" 0; then
    journalctl -u "$SERVICE" -n 30 --no-pager >&2 || true
    die 'The actual service failed the end-to-end proxy test.'
  fi
  systemctl is-active --quiet "$SERVICE" || die 'Service stopped after its proxy test.'
  systemctl enable "$SERVICE"
  helper text "$STATE" > "$INFO"
  chmod 600 "$INFO"
  manager_install
  COMMITTED=1
  say '[7/7] Server-side installation and end-to-end tests passed.'
  cat "$INFO"
  say ''
  say "Service: systemctl status $SERVICE --no-pager -l"
  say "Client info: $INFO"
  say 'Now select this new node in v2rayN, enable its system proxy, and test from your network.'
  say 'The VPS self-test does not verify provider firewall rules or the client-to-VPS Internet path.'
}

