  candidate=$(mktemp "$LIB/.manager.XXXXXX")
  { manager_header; declare -f say die fetch find_python helper stop_pair save_iptables undo_firewall cleanup port_busy wait_listener download_core public_address proxy_requests test_proxy choose_target allow_firewall write_unit guard_owned check_installed uninstall_owned install_main manager_header manager_install runtime_init backup_node firewall_open export_node ss_proxy_test preflight_state service_ready verify_running apply_state config_command ss_command ensure_openssl sharing_certificate share_command download_new_core update_core update_manager manager_uninstall manager_help main; printf '%s\n' 'if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then main "$@"; fi'; } > "$candidate"
  chmod 700 "$candidate"
