[[ $(id -u) == 0 ]] || { echo 'Run with sudo/root.' >&2; exit 1; }
exec bash /usr/local/lib/bwh45-reality/manager.sh "$@"
LAUNCHER_SCRIPT
  chmod 755 "$launcher"
  mv -f -- "$launcher" "$LAUNCHER"
