firewall_open() {
  local number=$1 proto=$2 iface zone rc
  [[ "$number" =~ ^[0-9]+$ && "$number" -ge 1 && "$number" -le 65535 ]] || die 'Invalid firewall port.'
  [[ "$proto" == tcp || "$proto" == udp ]] || die 'Invalid firewall protocol.'
  if command -v firewall-cmd >/dev/null 2>&1 && systemctl is-active --quiet firewalld.service; then
    iface=$(ip -4 route show default | awk 'NR==1 {for(i=1;i<NF;i++)if($i=="dev"){print $(i+1);exit}}')
    zone=$(firewall-cmd --get-zone-of-interface="$iface" 2>/dev/null || true)
    [[ -n "$zone" && "$zone" != 'no zone' ]] || zone=$(firewall-cmd --get-default-zone)
    [[ "$zone" =~ ^[A-Za-z0-9_-]+$ ]] || die 'Invalid firewalld zone.'
    if firewall-cmd --zone="$zone" --query-port="$number/$proto" >/dev/null; then :; else
      rc=$?; [[ "$rc" == 1 ]] || return 1
      firewall-cmd --zone="$zone" --add-port="$number/$proto" >/dev/null || return 1
      printf 'firewalld %s %s %s runtime\n' "$zone" "$number" "$proto" >> "$WORK/fw-changes"
    fi
    if firewall-cmd --permanent --zone="$zone" --query-port="$number/$proto" >/dev/null; then :; else
      rc=$?; [[ "$rc" == 1 ]] || return 1
      firewall-cmd --permanent --zone="$zone" --add-port="$number/$proto" >/dev/null || return 1
      printf 'firewalld %s %s %s permanent\n' "$zone" "$number" "$proto" >> "$WORK/fw-changes"
    fi
  elif command -v ufw >/dev/null 2>&1 && ufw status | awk '/^Status: active$/{ok=1} END{exit !ok}'; then
    if ! ufw status | awk -v rule="$number/$proto" '$1==rule && /ALLOW/{ok=1}END{exit !ok}'; then
      ufw allow "$number/$proto" comment "$OWNER" >/dev/null || return 1
      printf 'ufw none %s %s runtime\n' "$number" "$proto" >> "$WORK/fw-changes"
    fi
  elif command -v iptables >/dev/null 2>&1; then
    if ! iptables -C INPUT -p "$proto" --dport "$number" -m comment --comment "$OWNER" -j ACCEPT 2>/dev/null; then
      iptables -I INPUT 1 -p "$proto" --dport "$number" -m comment --comment "$OWNER" -j ACCEPT || return 1
      printf 'iptables none %s %s runtime\n' "$number" "$proto" >> "$WORK/fw-changes"
    fi
    save_iptables || return 1
  fi
}
allow_firewall() { firewall_open "$PORT" tcp; }
undo_firewall() {
  local kind zone number proto scope
  [[ -n "$WORK" && -f "$WORK/fw-changes" ]] || return 0
  while read -r kind zone number proto scope; do
    case "$kind" in
      firewalld)
        if [[ "$scope" == permanent ]]; then firewall-cmd --permanent --zone="$zone" --remove-port="$number/$proto" >/dev/null 2>&1 || true
        else firewall-cmd --zone="$zone" --remove-port="$number/$proto" >/dev/null 2>&1 || true; fi ;;
      ufw) ufw --force delete allow "$number/$proto" >/dev/null 2>&1 || true ;;
      iptables) iptables -D INPUT -p "$proto" --dport "$number" -m comment --comment "$OWNER" -j ACCEPT 2>/dev/null || true ;;
    esac
  done < "$WORK/fw-changes"
  save_iptables || true
  : > "$WORK/fw-changes"
}
export_node() {
  helper exports "$STATE" "$BASE/exports"
  install -m 600 "$BASE/exports/client.json" "$BASE/client.json"
  install -m 600 "$BASE/exports/info.txt" "$INFO"
}
ss_proxy_test() {
  local state=$1 number=$2 make_server=$3 socks
  stop_pair
  if [[ "$make_server" == 1 ]]; then
    helper ss-server "$state" 127.0.0.1 "$number" > "$WORK/ss-server.json" || return 1
    "$XRAY" run -test -config "$WORK/ss-server.json" >/dev/null 2>&1 || return 1
    "$XRAY" run -config "$WORK/ss-server.json" >"$WORK/ss-server.log" 2>&1 9>&- &
    SERVER_PID=$!
    wait_listener "$number" "$SERVER_PID" || { stop_pair; return 1; }
  fi
  socks=$(helper free-port) || { stop_pair; return 1; }
  helper ss-client "$state" 127.0.0.1 "$number" "$socks" > "$WORK/ss-client.json" || { stop_pair; return 1; }
  "$XRAY" run -config "$WORK/ss-client.json" > "$WORK/ss-client.log" 2>&1 9>&- &
  CLIENT_PID=$!
  if ! wait_listener "$socks" "$CLIENT_PID" || ! proxy_requests "$socks" || ! helper udp-test "$socks"; then stop_pair; return 1; fi
  stop_pair
}
preflight_state() {
  local state=$1 p
  helper server "$state" 0.0.0.0 "$(helper field "$state" port)" > "$WORK/candidate.json" || return 1
  "$XRAY" run -test -config "$WORK/candidate.json" || return 1
  p=$(helper free-port)
  test_proxy "$state" "$p" 1 || return 1
  if [[ $(helper ss-field "$state" enabled) == 1 ]]; then
    p=$(helper free-port)
    ss_proxy_test "$state" "$p" 1 || return 1
  fi
}
service_ready() {
  local n number=$1
  for n in {1..50}; do
    if systemctl is-active --quiet "$SERVICE" && helper listening "$number" >/dev/null 2>&1; then return 0; fi
    sleep 0.2
  done
  return 1
}
verify_running() {
  local state=$1 p
  p=$(helper field "$state" port)
  service_ready "$p" && test_proxy "$state" "$p" 0 || return 1
  if [[ $(helper ss-field "$state" enabled) == 1 ]]; then ss_proxy_test "$state" "$(helper ss-field "$state" port)" 0 || return 1; fi
}
apply_state() {
  local candidate=$1 oldp newp ssp oldss active=0 backup
  oldp=$(helper field "$STATE" port);newp=$(helper field "$candidate" port)
  if [[ "$newp" != "$oldp" ]] && port_busy "$newp"; then die "TCP $newp is occupied."; fi
  if [[ $(helper ss-field "$candidate" enabled) == 1 ]]; then
    ssp=$(helper ss-field "$candidate" port)
    oldss=
    if [[ $(helper ss-field "$STATE" enabled) == 1 ]];then oldss=$(helper ss-field "$STATE" port);fi
    if [[ "$ssp" != "$oldss" ]] && port_busy "$ssp"; then die "SS TCP $ssp is occupied."; fi
    if [[ "$ssp" != "$oldss" ]] && ss -lnu | awk -v p=":$ssp$" 'NR>1 && $4~p{f=1}END{exit !f}'; then die "SS UDP $ssp is occupied."; fi
  fi
  preflight_state "$candidate" || die 'Candidate failed proxy tests; current configuration was preserved.'
  backup=$(backup_node)
  systemctl is-active --quiet "$SERVICE" && active=1 || true
  TX_BACKUP=$backup;TX_RUNNING=$active;TX_CORE=0
  firewall_open "$newp" tcp || { undo_firewall; die 'Firewall change failed; node configuration preserved.'; }
  if [[ $(helper ss-field "$candidate" enabled) == 1 ]]; then
    firewall_open "$ssp" tcp && firewall_open "$ssp" udp || { undo_firewall; die 'SS firewall change failed.'; }
  fi
  install -m 600 "$candidate" "$STATE"
  install -m 600 "$WORK/candidate.json" "$CONFIG"
  if [[ "$active" == 1 ]] && { ! systemctl restart "$SERVICE" || ! verify_running "$STATE"; }; then
    cp -a -- "$backup/state/." "$BASE/"
    systemctl restart "$SERVICE" || true
    undo_firewall
    die "Service update failed and was rolled back. Backup: $backup"
  fi
  export_node
  systemctl stop "$SHARE_SERVICE" >/dev/null 2>&1 || true
  TX_BACKUP=
  say "Configuration applied. Backup: $backup"
  [[ "$active" == 1 ]] || say 'The service remains stopped.'
}
config_command() {
  local field value choice candidate=$WORK/changed.json
  cp -- "$STATE" "$candidate"
  if [[ $# == 0 ]]; then
    printf '1 Port  2 Client address  3 SNI/target  4 Fingerprint  5 New UUID  6 Rotate REALITY keys  7 Node name  0 Cancel\n'
    read -r -p '> ' choice
    case "$choice" in
      1) set -- --port;; 2) set -- --address;; 3) set -- --sni;; 4) set -- --fingerprint;;
      5) set -- --new-uuid;; 6) set -- --rotate-keys;; 7) set -- --name;; 0) return;; *) die 'Invalid selection.';;
    esac
    case "$1" in --new-uuid|--rotate-keys) ;; *) read -r -p 'New value: ' value; set -- "$1" "$value";; esac
  fi
  while [[ $# -gt 0 ]]; do
    field=$1;shift
    case "$field" in
      --port|--address|--sni|--fingerprint|--name)
        [[ $# -gt 0 ]] || die 'Missing configuration value.'
        value=$1;shift
        case "$field" in --fingerprint) field=fp;; *) field=${field#--};; esac
        printf '%s\n' "$value" > "$WORK/value";;
      --new-uuid) field=uuid;"$BIN" uuid > "$WORK/value";;
      --rotate-keys) field=rekey;"$BIN" x25519 > "$WORK/value";;
      *) die 'Unknown config option.';;
    esac
    helper patch "$candidate" "$field" "$WORK/value" > "$WORK/next.json"
    mv -- "$WORK/next.json" "$candidate"
  done
  apply_state "$candidate"
  helper text "$STATE"
}
ss_command() {
  local mode=on number='' method='' passfile='' choice answer
  if [[ $# == 0 ]]; then
    printf '1 Enable/edit Shadowsocks  2 Disable Shadowsocks  3 Show Shadowsocks  0 Cancel\n'
    read -r -p '> ' choice
    case "$choice" in
      1)
        read -r -p 'TCP/UDP port [8388 or current]: ' number
        read -r -p 'Method [2022-blake3-aes-128-gcm or current]: ' method
        read -r -s -p 'Password/key [Enter = keep or generate]: ' answer;printf '\n'
        printf '%s\n' "$answer" > "$WORK/ss-password";passfile=$WORK/ss-password;;
      2) mode=off;; 3) helper ss-text "$STATE";return;; 0) return;; *) die 'Invalid selection.';;
    esac
  else
    while [[ $# -gt 0 ]]; do
      case "$1" in
        --enable) mode=on;shift;; --disable) mode=off;shift;;
        --port) [[ $# -gt 1 ]] || die 'Missing SS port';number=$2;shift 2;;
        --method) [[ $# -gt 1 ]] || die 'Missing SS method';method=$2;shift 2;;
        --password-stdin) IFS= read -r answer;printf '%s\n' "$answer" > "$WORK/ss-password";passfile=$WORK/ss-password;shift;;
        *) die 'Unknown ss option.';;
      esac
    done
  fi
  helper ss-patch "$STATE" "$mode" "$number" "$method" "$passfile" > "$WORK/ss-state.json"
  apply_state "$WORK/ss-state.json"
  if [[ "$mode" == on ]]; then helper ss-text "$STATE";else say 'Shadowsocks disabled; REALITY credentials preserved.';fi
}
ensure_openssl() {
  command -v openssl >/dev/null 2>&1 && return 0
  command -v yum >/dev/null 2>&1 || die 'Install the openssl command with your OS package manager before generating HTTPS links.'
  [[ -r /etc/centos-release && -f /etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-7 ]] || die 'Install openssl first.'
  say 'Installing the missing openssl dependency from signed CentOS 7 vault packages.'
  mkdir -m 700 "$WORK/yum-repos"
  cat > "$WORK/yum-repos/vault.repo" <<'VAULT_REPO'
[bwh-centos7-base]
name=CentOS 7.9.2009 base
baseurl=https://vault.centos.org/7.9.2009/os/$basearch/
enabled=1
gpgcheck=1
gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-7
[bwh-centos7-updates]
name=CentOS 7.9.2009 updates
baseurl=https://vault.centos.org/7.9.2009/updates/$basearch/
enabled=1
gpgcheck=1
gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-7
VAULT_REPO
  yum -y --setopt="reposdir=$WORK/yum-repos" --disablerepo='*' --enablerepo=bwh-centos7-base,bwh-centos7-updates install openssl
}
sharing_certificate() {
  local host=$1 kind=DNS
  mkdir -p -m 700 "$BASE/share-tls"
  SHARE_CRT=$BASE/share-tls/cert.pem;SHARE_PRIV=$BASE/share-tls/key.pem
  if [[ -n "${SHARE_CERT:-}" || -n "${SHARE_KEY:-}" ]]; then
    [[ -n "${SHARE_CERT:-}" && -n "${SHARE_KEY:-}" ]] || die 'Set both SHARE_CERT and SHARE_KEY.'
    install -m 600 "$SHARE_CERT" "$SHARE_CRT"
    install -m 600 "$SHARE_KEY" "$SHARE_PRIV"
    rm -f -- "$BASE/share-tls/ca.pem"
    return
  fi
  ensure_openssl
  if [[ -f "$SHARE_CRT" && -f "$SHARE_PRIV" && -f "$BASE/share-tls/ca.pem" &&
        -f "$BASE/share-tls/host" && $(cat "$BASE/share-tls/host") == "$host" ]] &&
        openssl x509 -in "$SHARE_CRT" -checkend 86400 -noout >/dev/null 2>&1;then return;fi
  [[ "$host" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] && kind=IP || true
  cat > "$WORK/ca.cnf" <<'CA_CONFIG'
[req]
distinguished_name=dn
x509_extensions=ext
prompt=no
[dn]
CN=bwh45 Temporary Sharing CA
[ext]
basicConstraints=critical,CA:TRUE,pathlen:0
keyUsage=critical,keyCertSign,cRLSign
subjectKeyIdentifier=hash
CA_CONFIG
  cat > "$WORK/certificate.cnf" <<CERT_CONFIG
[req]
distinguished_name=dn
prompt=no
[dn]
CN=$host
[ext]
subjectAltName=$kind:$host
basicConstraints=critical,CA:FALSE
keyUsage=critical,digitalSignature,keyEncipherment
extendedKeyUsage=serverAuth
authorityKeyIdentifier=keyid,issuer
CERT_CONFIG
  openssl req -x509 -newkey rsa:2048 -sha256 -nodes -days 31 -config "$WORK/ca.cnf" \
    -keyout "$WORK/ca.key" -out "$WORK/ca.crt" >"$WORK/cert.log" 2>&1
  openssl req -new -newkey rsa:2048 -sha256 -nodes -config "$WORK/certificate.cnf" \
    -keyout "$WORK/share.key" -out "$WORK/share.csr" >>"$WORK/cert.log" 2>&1
  openssl x509 -req -sha256 -days 30 -in "$WORK/share.csr" -CA "$WORK/ca.crt" \
    -CAkey "$WORK/ca.key" -CAcreateserial -extfile "$WORK/certificate.cnf" -extensions ext \
    -out "$WORK/share.crt" >>"$WORK/cert.log" 2>&1
  cat "$WORK/share.crt" "$WORK/ca.crt" > "$WORK/share-chain.crt"
  install -m 600 "$WORK/share-chain.crt" "$SHARE_CRT"
  install -m 600 "$WORK/share.key" "$SHARE_PRIV"
  install -m 600 "$WORK/ca.crt" "$BASE/share-tls/ca.pem"
  # The CA private key is temporary and is deleted with WORK; only the server leaf key persists.
  printf '%s\n' "$host" > "$BASE/share-tls/host"
}
share_command() {
  local file=$1 host number ttl token folder expires now baseurl
  case "$file" in ss-*) [[ $(helper ss-field "$STATE" enabled) == 1 ]] || die 'Enable Shadowsocks with v2ray ss first.';; esac
  host=${SHARE_HOST:-$(helper field "$STATE" address)}
  number=${SHARE_PORT:-8443};ttl=${SHARE_TTL:-600}
  helper hostname "$host" >/dev/null
  [[ "$number" =~ ^[0-9]+$ && "$number" -ge 1 && "$number" -le 65535 ]] || die 'Invalid sharing port.'
  [[ "$number" != "$(helper field "$STATE" port)" ]] || die 'Share port conflicts with REALITY.'
  if [[ $(helper ss-field "$STATE" enabled) == 1 && "$number" == "$(helper ss-field "$STATE" port)" ]]; then die 'Share port conflicts with Shadowsocks.';fi
  export_node
  now=$(date +%s)
  if [[ -z "${SHARE_CERT:-}" && -z "${SHARE_KEY:-}" && -f "$BASE/share.json" ]] && systemctl is-active --quiet "$SHARE_SERVICE"; then
    expires=$(helper meta-field "$BASE/share.json" expires)
    if [[ "$expires" -gt "$((now+10))" &&
          $(helper meta-field "$BASE/share.json" port) == "$number" &&
          $(helper meta-field "$BASE/share.json" host) == "$host" ]]; then
      token=$(helper meta-field "$BASE/share.json" token)
      folder=$(helper meta-field "$BASE/share.json" folder)
      cp -a -- "$BASE/exports/." "$folder/"
    fi
  fi
  if [[ -z "${token:-}" ]]; then
    systemctl stop "$SHARE_SERVICE" >/dev/null 2>&1 || true
    port_busy "$number" && die "Share TCP $number is occupied."
    sharing_certificate "$host"
    folder=$(mktemp -d "$BASE/share.XXXXXX")
    cp -a -- "$BASE/exports/." "$folder/"
    helper make-share "$host" "$number" "$folder" "$ttl" "$SHARE_CRT" "$SHARE_PRIV" > "$BASE/share.json"
    token=$(helper meta-field "$BASE/share.json" token)
    expires=$(helper meta-field "$BASE/share.json" expires)
    cat > "$SHARE_UNIT" <<SHARE_UNIT_BODY
# Managed by bwh45-reality-v2
[Unit]
Description=bwh45 temporary HTTPS node sharing
After=network.target
[Service]
Type=simple
ExecStart=/usr/bin/bash $LIB/manager.sh --serve-share
Restart=no
SHARE_UNIT_BODY
    chmod 644 "$SHARE_UNIT"
    firewall_open "$number" tcp || { undo_firewall;die 'Could not allow sharing port.'; }
    systemctl daemon-reload
    systemctl start "$SHARE_SERVICE"
    for attempt in {1..30};do
      helper listening "$number" >/dev/null 2>&1 && break
      sleep 0.2
    done
    systemctl is-active --quiet "$SHARE_SERVICE" || { undo_firewall;die 'HTTPS sharing failed to start.'; }
  fi
  token=$(helper share-token "$BASE/share.json" "$file")
  baseurl="https://$host:$number/$token"
  say "$baseurl/$file"
  say "Private HTTPS link; expires at Unix time $expires. Provider firewall must allow TCP $number."
  say 'Default HTTPS certificate uses a local CA and is not browser-trusted. Verify this SHA256 fingerprint before accepting it:'
  if command -v openssl >/dev/null 2>&1;then openssl x509 -in "$BASE/share-tls/cert.pem" -noout -fingerprint -sha256;fi
  say "Local export: $BASE/exports/$file"
}
download_new_core() {
  local target=${1:-} url actual expected
  if [[ -z "$target" ]];then
    url=$(fetch -o /dev/null -w '%{url_effective}' https://github.com/XTLS/Xray-core/releases/latest)
    target=${url##*/};target=${target#v}
  else target=${target#v};fi
  [[ "$target" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || die 'Invalid core version.'
  NEW_CORE=$target
  url="https://github.com/XTLS/Xray-core/releases/download/v$target/Xray-linux-64.zip"
  fetch "$url" -o "$WORK/new-core.zip"
  fetch "$url.dgst" -o "$WORK/new-core.dgst"
  expected=$(awk -F= '/^[[:space:]]*SHA(2-)?256[[:space:]]*=/ {gsub(/[[:space:]]/,"",$2);print tolower($2);exit}' "$WORK/new-core.dgst")
  [[ "$expected" =~ ^[a-f0-9]{64}$ ]] || die 'Missing official core checksum.'
  actual=$(sha256sum "$WORK/new-core.zip" | awk '{print $1}')
  [[ "$actual" == "$expected" ]] || die 'Official core checksum mismatch.'
  helper extract "$WORK/new-core.zip" "$WORK/new-xray"
  chmod 700 "$WORK/new-xray"
  "$WORK/new-xray" version
}
update_core() {
  local active=0 backup
  download_new_core "${1:-}"
  XRAY=$WORK/new-xray
  preflight_state "$STATE" || die 'New core failed real proxy tests; installed core preserved.'
  backup=$(backup_node)
  cp -p -- "$BIN" "$backup/xray"
  systemctl is-active --quiet "$SERVICE" && active=1 || true
  TX_BACKUP=$backup;TX_RUNNING=$active;TX_CORE=1
  install -m 700 "$XRAY" "$LIB/.xray-new"
  mv -f -- "$LIB/.xray-new" "$BIN"
  XRAY=$BIN
  if [[ "$active" == 1 ]] && { ! systemctl restart "$SERVICE" || ! verify_running "$STATE"; };then
    install -m 700 "$backup/xray" "$LIB/.xray-old";mv -f -- "$LIB/.xray-old" "$BIN"
    systemctl restart "$SERVICE" || true
    die "Core upgrade rolled back. Backup: $backup"
  fi
  helper core-version "$STATE" "$NEW_CORE" > "$WORK/new-state.json"
  install -m 600 "$WORK/new-state.json" "$STATE"
  export_node
  TX_BACKUP=
  say "Core updated to $NEW_CORE. Node credentials preserved. Backup: $backup"
}
update_manager() {
  local version hash actual commit
  fetch "$REPO_API/git/ref/heads/main" -o "$WORK/repo-head.json"
  commit=$(helper repo-head "$WORK/repo-head.json")
  fetch "$REPO_RAW/$commit/manifest.json" -o "$WORK/manifest.json"
  read -r version hash < <(helper manifest "$WORK/manifest.json")
  if [[ "$version" == "$VERSION" ]];then say "Manager $VERSION is already current.";return;fi
  "$PY" - "$version" "$VERSION" <<'PY_VERSION'
import sys
assert tuple(map(int,sys.argv[1].split('.')))>tuple(map(int,sys.argv[2].split('.'))),'Manager downgrade refused'
PY_VERSION
  fetch "$REPO_RAW/$commit/install.sh" -o "$WORK/new-manager.sh"
  actual=$(sha256sum "$WORK/new-manager.sh" | awk '{print $1}')
  [[ "$actual" == "$hash" ]] || die 'Manager SHA256 mismatch; no files were replaced.'
  bash -n "$WORK/new-manager.sh"
  bash "$WORK/new-manager.sh" --self-check >/dev/null
  [[ $(bash "$WORK/new-manager.sh" --version) == "$version" ]] || die 'Manager manifest/version mismatch.'
  # Release this process lock; the verified installer acquires it itself.
  flock -u 9
  bash "$WORK/new-manager.sh" --manager-only
}
manager_uninstall() {
  local backup
  backup=$(backup_node)
  systemctl stop "$SHARE_SERVICE" >/dev/null 2>&1 || true
  systemctl disable "$SHARE_SERVICE" >/dev/null 2>&1 || true
  systemctl stop "$SERVICE"
  systemctl disable "$SERVICE"
  if [[ -f "$LAUNCHER" ]];then head -n 3 "$LAUNCHER" | awk '/Managed by bwh45-reality-v2/{ok=1}END{exit !ok}' && rm -f -- "$LAUNCHER";fi
  rm -f -- "$UNIT" "$SHARE_UNIT" "$INFO"
  rm -rf -- "$BASE" "$LIB"
  systemctl daemon-reload
  say "Uninstalled. Configuration backup: $backup"
  say 'Existing firewall rules were preserved.'
}
manager_help() {
  cat <<'HELP_TEXT'
v2ray info         Show REALITY node information and import URI
v2ray config       Change address, port, SNI, fingerprint, name, UUID or keys
v2ray link         Temporary HTTPS Xray client configuration file link
v2ray infolink     Temporary HTTPS node information link
v2ray qr           Temporary HTTPS REALITY QR image link
v2ray ss           Enable/change/disable Shadowsocks
v2ray ssinfo       Show Shadowsocks information and import URI
v2ray ssqr         Temporary HTTPS Shadowsocks QR image link
v2ray status       Service status
v2ray start        Start and check the node
v2ray stop         Stop the node
v2ray restart      Restart and check the node
v2ray log          Journal logs (add -f to follow)
v2ray update       Verify and update official stable Xray core
v2ray update.sh    Verify and update this manager
v2ray uninstall    Back up and uninstall the node and manager
v2ray check        Real REALITY/SS proxy self-test
HELP_TEXT
}
main() {
  local command=${1:-} option
  if [[ -z "$command" ]];then
    if [[ "$SCRIPT_KIND" == manager ]];then manager_help;return;else command=--install;fi
  else shift;fi
  case "$command" in
    --version) say "$VERSION";return;;
    --help|help) manager_help;return;;
    --self-check) find_python;helper self-check;return;;
    --serve-share) find_python;helper serve-share "$BASE/share.json";return;;
    --install) install_main --install;return;;
    --check) command=check;;
    --uninstall) command=uninstall;;
  esac
  runtime_init
  case "$command" in
    --manager-only) manager_install;;
    info) say "Manager $VERSION / Xray $(helper field "$STATE" core_version)";helper text "$STATE";;
    config) config_command "$@";;
    link) share_command client.json;; infolink) share_command info.txt;; qr) share_command qr.svg;;
    ss) ss_command "$@";; ssinfo) helper ss-text "$STATE";; ssqr) share_command ss-qr.svg;;
    status) systemctl --no-pager -l status "$SERVICE" || true;;
    start) systemctl start "$SERVICE";verify_running "$STATE";;
    stop) systemctl stop "$SERVICE";say 'Node stopped.';;
    restart) systemctl restart "$SERVICE";verify_running "$STATE";;
    log) exec 9>&-;journalctl -u "$SERVICE" -n 50 --no-pager "$@";;
    update) update_core "$@";; update.sh) update_manager;;
    uninstall) manager_uninstall;; check) check_installed;;
    *) die 'Unknown command; run v2ray help.';;
  esac
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then main "$@"; fi
